// C++17 (chrono literals like 1ms are C++14)
#include <chrono>
#include <iostream>

int main() {
    volatile double acc = 0.0;   // keeps the loop alive under optimisation
    const auto t0 = std::chrono::steady_clock::now();
    for (int i = 0; i < 1'000'000; ++i) acc += i * 1.000001;
    const auto t1 = std::chrono::steady_clock::now();
    const auto ns = std::chrono::duration_cast<std::chrono::nanoseconds>(t1 - t0).count();
    std::cout << ns << " ns total, " << static_cast<double>(ns) / 1e6 << " ns/op\n";
}

