// C++17
#include <filesystem>
#include <iostream>
namespace fs = std::filesystem;

int main() {
    std::uintmax_t total = 0;
    for (const auto& entry : fs::directory_iterator("data/ticks")) {
        if (entry.is_regular_file() && entry.path().extension() == ".csv")
            total += entry.file_size();
    }
    std::cout << total << " bytes of CSV\n";
}

// C++17 - the explicit-loop equivalent
#include <iostream>
#include <vector>

int main() {
    const std::vector<int> fills{3, 1, 4, 1, 5, 9, 2, 6};
    int sum = 0;
    for (int f : fills)
        if (f % 2 != 0) sum += f * 100;      // odd fills, in lots of 100
    std::cout << sum << "\n";               // 1900
}

// C++20 - the same computation as a lazy pipeline
#include <iostream>
#include <ranges>
#include <vector>

int main() {
    const std::vector<int> fills{3, 1, 4, 1, 5, 9, 2, 6};
    auto lots = fills
              | std::views::filter([](int f) { return f % 2 != 0; })
              | std::views::transform([](int f) { return f * 100; });
    int sum = 0;
    for (int lot : lots) sum += lot;         // pipeline runs here, lazily
    std::cout << sum << "\n";               // 1900
}

